from lxml import etree
from copy import deepcopy
from pathlib import Path
import zipfile, re, datetime, shutil

BASE=Path('documents/turn-2-redline-meridian.docx')
OUT=Path('output/turn-3-redline-gmra.docx')
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
R='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
CT='http://schemas.openxmlformats.org/package/2006/content-types'
ns={'w':W,'r':R}
q=lambda t: '{%s}%s'%(W,t)

with zipfile.ZipFile(BASE) as zin:
    files={n:zin.read(n) for n in zin.namelist()}
root=etree.fromstring(files['word/document.xml'])
body=root.find('.//w:body',ns)

# Accept Turn 2's historical revisions so this file is a clean Turn 2 base,
# then layer the Turn 3 changes on top.
def accept_revisions(parent):
    for child in list(parent):
        if child.tag==q('del'):
            parent.remove(child)
        elif child.tag==q('ins'):
            idx=parent.index(child)
            parent.remove(child)
            for sub in list(child):
                parent.insert(idx, sub); idx += 1
        else:
            accept_revisions(child)
accept_revisions(root)

# Helpers
def p_text(p):
    return ''.join(p.xpath('.//w:t/text()',namespaces=ns))
def all_paras():
    return root.xpath('.//w:body//w:p',namespaces=ns)
def find_p(pred):
    for p in all_paras():
        if pred(p_text(p)):
            return p
    raise RuntimeError('paragraph not found')
def find_all(pred):
    return [p for p in all_paras() if pred(p_text(p))]
def style_rpr(p):
    rpr=p.find('.//w:r/w:rPr',ns)
    if rpr is not None: return deepcopy(rpr)
    rpr=etree.Element(q('rPr'))
    rfonts=etree.SubElement(rpr,q('rFonts')); rfonts.set(q('ascii'),'Times New Roman'); rfonts.set(q('hAnsi'),'Times New Roman')
    sz=etree.SubElement(rpr,q('sz')); sz.set(q('val'),'22')
    return rpr
def clear_p(p):
    for child in list(p):
        if child.tag != q('pPr'):
            p.remove(child)
def add_run(container, text, kind='t', rpr=None):
    r=etree.SubElement(container,q('r'))
    if rpr is not None: r.append(deepcopy(rpr))
    el=etree.SubElement(r,q(kind)); el.text=text
    if text[:1].isspace() or text[-1:].isspace(): el.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    return r
def clean_p(p,text):
    rpr=style_rpr(p); clear_p(p); add_run(p,text,'t',rpr)
def rev_id():
    rev_id.n += 1; return str(rev_id.n)
rev_id.n=200
def tracked_p(p, old, new, only_insert=False):
    rpr=style_rpr(p); clear_p(p)
    if old and not only_insert:
        d=etree.SubElement(p,q('del')); d.set(q('id'),rev_id()); d.set(q('author'),'Pryor, Ashworth & Gelb LLP'); d.set(q('date'),'2025-04-17T00:00:00Z'); add_run(d,old,'delText',rpr)
    ins=etree.SubElement(p,q('ins')); ins.set(q('id'),rev_id()); ins.set(q('author'),'Pryor, Ashworth & Gelb LLP'); ins.set(q('date'),'2025-04-17T00:00:00Z'); add_run(ins,new,'t',rpr)
def make_p(template,text,old=None,only_insert=False):
    p=etree.Element(q('p'))
    pp=template.find('w:pPr',ns) if template is not None else None
    if pp is not None: p.append(deepcopy(pp))
    if old is None: clean_p(p,text)
    else: tracked_p(p,old,text,only_insert)
    return p
def replace_p_with_lines(target, lines):
    parent=target.getparent(); idx=parent.index(target); template=target
    parent.remove(target)
    for j,item in enumerate(lines):
        # item: (old,new) or (None,new)
        old,new=item if isinstance(item,tuple) else (None,item)
        parent.insert(idx+j, make_p(template,new,old,old is None))

def remove_between(start,end):
    parent=start.getparent(); assert parent is end.getparent()
    si=parent.index(start); ei=parent.index(end)
    for child in list(parent)[si+1:ei]:
        if child.tag==q('p'):
            parent.remove(child)

def set_text_start(starts,text):
    p=find_p(lambda s:s.startswith(starts)); clean_p(p,text); return p

# Cover metadata / revision note
set_text_start('Draft circulated by Buyer:', 'Draft circulated by Buyer: 14 March 2025')
